CREATE TABLE organization_settings (organization_id uuid PRIMARY KEY REFERENCES organizations(id) ON DELETE CASCADE, closure_policy text NOT NULL DEFAULT 'STAFF_ONLY' CHECK(closure_policy IN ('STAFF_ONLY','REQUESTER_CONFIRMATION','AUTO_EXPIRE')), reopen_window_days smallint NOT NULL DEFAULT 7 CHECK(reopen_window_days BETWEEN 0 AND 90), business_timezone text NOT NULL DEFAULT 'Asia/Tehran', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE response_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL CHECK(char_length(name) BETWEEN 2 AND 120), body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 5000), created_by_user_id uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,name));
ALTER TABLE organization_settings ENABLE ROW LEVEL SECURITY; ALTER TABLE response_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY organization_settings_tenant ON organization_settings USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
CREATE POLICY response_templates_tenant ON response_templates USING(organization_id=app.current_organization_id()) WITH CHECK(organization_id=app.current_organization_id());
GRANT SELECT,INSERT,UPDATE,DELETE ON organization_settings,response_templates TO jupiter_app;
